testCases.expectedOutput:
BoundedContext Procurement {
    domain {
        Aggregate PurchaseOrder {
            purchaseOrderId: UUID @identity
            supplierId: String @required
            requesterId: String @required
            lines: List<PurchaseOrderLine>
            totalAmount: Money
            status: String @default("DRAFT")
            approvedAt: DateTime?

            Entity PurchaseOrderLine {
                lineId: UUID @identity
                itemCode: String @required
                quantity: Int @min(1)
                unitCost: Money @required
            }

            operations {
                when submitting purchase order:
                require that:
                    - supplierId is not empty
                    - requesterId is not empty
                    - lines is not empty
                then:
                    - calculate totalAmount as sum of line costs
                    - set status to "SUBMITTED"
                emit PurchaseOrderSubmitted with purchaseOrderId

                when approving purchase order with approvedAt and approverId:
                require that:
                    - status is "SUBMITTED"
                    - approverId is not empty
                    - totalAmount is greater than 0
                then:
                    - set status to "APPROVED"
                    - set approvedAt to approvedAt
                emit PurchaseOrderApproved with purchaseOrderId and approverId
            }
        }

        ValueObject Money {
            amount: Decimal @min(0)
            currency: String @required @maxLength(3)
        }

        DomainService ApprovalPolicy {
            when checking approval requirement with totalAmount as Money and requesterId as String:
            then:
                - calculate approvalRequired as totalAmount is greater than 1000
        }
    }

    events {
        DomainEvent PurchaseOrderSubmitted {
            purchaseOrderId: UUID
            submittedAt: DateTime
            total: Money
        }

        DomainEvent PurchaseOrderApproved {
            purchaseOrderId: UUID
            approverId: String
            approvedAt: DateTime
        }
    }

    factories {
        Factory PurchaseOrderFactory {
            when creating PurchaseOrder from supplierId with requesterId and lines:
            require that:
                - lines is not empty
            then:
                - create PurchaseOrder with supplierId and requesterId and lines
            return PurchaseOrder
        }
    }
}
